//! 🚚️ Typed list commit moves original row owners through pre-admitted headers.
use super::keyed_plan::Origin;
use semio_framework_os_kernel::ApplyCapability;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retirement::RetireOwned,retained_clone::{RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
use std::mem::{size_of,ManuallyDrop};
/// 📤 An authored insertion transfers its actual typed row without cloning its children.
pub trait OwnedInsertion<R>:RetireOwned{fn into_row(self)->R;}
impl<R:RetireOwned> OwnedInsertion<R> for R{fn into_row(self)->R{self}}
/// 🧳 Every original, partial and displaced typed list remains funded-closeable.
pub struct TypedListMove<R:RetireOwned,I:OwnedInsertion<R>>{original:ManuallyDrop<Option<Vec<R>>>,authored:ManuallyDrop<Option<Vec<I>>>,held:ManuallyDrop<Option<Vec<Option<R>>>>,inserted:ManuallyDrop<Option<Vec<Option<R>>>>,output:ManuallyDrop<Option<Vec<R>>>,retirement:RetainedCloneClose,counts:(usize,usize,usize),phase:u8,index:usize,closing:bool}
impl<R:RetireOwned,I:OwnedInsertion<R>> Default for TypedListMove<R,I>{fn default()->Self{Self::new()}}
impl<R:RetireOwned,I:OwnedInsertion<R>> TypedListMove<R,I>{
 pub fn new()->Self{Self{original:ManuallyDrop::new(Some(Vec::new())),authored:ManuallyDrop::new(Some(Vec::new())),held:ManuallyDrop::new(Some(Vec::new())),inserted:ManuallyDrop::new(Some(Vec::new())),output:ManuallyDrop::new(Some(Vec::new())),retirement:Default::default(),counts:(0,0,0),phase:0,index:0,closing:false}}
 fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<R>()*4+size_of::<I>()*2+size_of::<Self>()*2,depth:1,..Default::default()}}
 fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
 pub fn reserve_demand(&self,held:usize,inserted:usize,output:usize)->Result<RetirementDemand,ValueError>{if self.phase!=0||self.closing{return Err(Self::fault("typed list reserve already settled"))}let capacity=held.checked_add(inserted).and_then(|n|n.checked_mul(size_of::<Option<R>>())).and_then(|n|output.checked_mul(size_of::<R>()).and_then(|out|n.checked_add(out))).ok_or_else(||Self::fault("typed output header extent overflow"))?;Ok(RetirementDemand{capacity_bytes:capacity,..Self::fixed()})}
 pub fn reserve(&mut self,held:usize,inserted:usize,output:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.reserve_demand(held,inserted,output)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}self.counts=(held,inserted,output);let(left,right,out)=(self.held.as_mut().expect("original header slots"),self.inserted.as_mut().expect("authored header slots"),self.output.as_mut().expect("output headers"));let result=left.try_reserve_exact(held).and_then(|_|right.try_reserve_exact(inserted)).and_then(|_|out.try_reserve_exact(output));let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:left.capacity()*size_of::<Option<R>>()+right.capacity()*size_of::<Option<R>>()+out.capacity()*size_of::<R>(),..Default::default()};if result.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(Self::fault("typed output header reservation failed").with_retained_progress(p))}self.phase=1;Ok(RetainedCloneStep::Complete(p))}
 pub fn commit_demand(&self)->Result<RetirementDemand,ValueError>{if self.closing||self.phase==0||self.phase>5{return Err(Self::fault("typed list commit is not admitted"))}Ok(Self::fixed())}
 pub fn capture(&mut self,post:&mut Vec<R>,authored:&mut Option<Vec<I>>,g:RetainedCloneGrant,_capability:ApplyCapability)->Result<RetainedCloneStep,ValueError>{self.capture_owned(post,authored,g)}
 fn capture_owned(&mut self,post:&mut Vec<R>,authored:&mut Option<Vec<I>>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if self.phase!=1{return Err(Self::fault("typed original capture out of order"))}let d=self.commit_demand()?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if post.len()!=self.counts.0||authored.as_ref().is_none_or(|rows|rows.len()!=self.counts.1){return Err(Self::fault("typed original source extent changed after preflight"))}*self.original=Some(std::mem::take(post));*self.authored=authored.take();self.phase=2;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn advance(&mut self,post:&mut Vec<R>,origins:&[Option<Origin>],g:RetainedCloneGrant,_capability:ApplyCapability)->Result<RetainedCloneStep,ValueError>{self.advance_owned(post,origins,g)}
 fn advance_owned(&mut self,post:&mut Vec<R>,origins:&[Option<Origin>],g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if self.phase<2{return Err(Self::fault("typed list original capture is pending"))}let d=self.commit_demand()?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if self.phase==5{return Ok(RetainedCloneStep::Complete(Default::default()))}if self.phase==2{if let Some(row)=self.original.as_mut().expect("captured original list").pop(){self.held.as_mut().expect("reserved original slots").push(Some(row))}else{self.phase=3}return Ok(RetainedCloneStep::Progress(p))}if self.phase==3{if let Some(row)=self.authored.as_mut().expect("captured authored list").pop(){self.inserted.as_mut().expect("reserved authored slots").push(Some(row.into_row()))}else{self.phase=4}return Ok(RetainedCloneStep::Progress(p))}if origins.len()!=self.counts.2{return Err(Self::fault("typed final extent changed after preflight"))}if self.index<origins.len(){let at=origins[self.index].ok_or_else(||Self::fault("typed output origin is absent"))?;let slots=if at.inserted{self.inserted.as_mut().expect("authored row slots")}else{self.held.as_mut().expect("original row slots")};let index=slots.len().checked_sub(at.index+1).ok_or_else(||Self::fault("typed output source lies past its original extent"))?;let row=slots.get_mut(index).and_then(Option::take).ok_or_else(||Self::fault("typed original row was consumed twice"))?;self.output.as_mut().expect("reserved final vector").push(row);self.index+=1;return Ok(RetainedCloneStep::Progress(p))}std::mem::swap(post,self.output.as_mut().expect("admitted final row vector"));self.phase=5;Ok(RetainedCloneStep::Complete(p))}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<Vec<R>>(false,&None,body)}if self.original.is_some(){return self.retirement.next_owner_demands::<Vec<R>>(true,&None,body)}if self.authored.is_some(){return self.retirement.next_owner_demands::<Vec<I>>(true,&None,body)}if self.held.is_some()||self.inserted.is_some(){return self.retirement.next_owner_demands::<Vec<Option<R>>>(true,&None,body)}if self.output.is_some(){return self.retirement.next_owner_demands::<Vec<R>>(true,&None,body)}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(Self::fault("typed original close not begun"))}let d=self.close_demand(g.maximum_copy_bytes)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if let Some(s)=self.retirement.begin_granted(&mut self.original,g)?{return Ok(RetainedCloneStep::Progress(s.progress()))}if let Some(s)=self.retirement.begin_granted(&mut self.authored,g)?{return Ok(RetainedCloneStep::Progress(s.progress()))}if let Some(s)=self.retirement.begin_granted(&mut self.held,g)?{return Ok(RetainedCloneStep::Progress(s.progress()))}if let Some(s)=self.retirement.begin_granted(&mut self.inserted,g)?{return Ok(RetainedCloneStep::Progress(s.progress()))}if let Some(s)=self.retirement.begin_granted(&mut self.output,g)?{return Ok(RetainedCloneStep::Progress(s.progress()))}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.original.is_none()&&self.authored.is_none()&&self.held.is_none()&&self.inserted.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
}
impl<R:RetireOwned,I:OwnedInsertion<R>> Drop for TypedListMove<R,I>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"typed list originals require funded close")}}

